// Recebe { "clientes": [ ... ] } e gera uma recomendação educativa por cliente.
const entrada = $input.first().json;
const clientes = entrada.body?.clientes ?? entrada.clientes;

if (!Array.isArray(clientes)) {
  throw new Error('Formato inválido. Envie um JSON com a propriedade "clientes" contendo uma lista.');
}

const mensagens = {
  Conservador: "Seu perfil é conservador. Em geral, vale estudar alternativas que priorizem preservação do capital e menor oscilação, como Tesouro Selic e CDBs com liquidez diária de instituições confiáveis. Compare riscos, taxas, liquidez e proteção do FGC quando aplicável.",
  Moderado: "Seu perfil é moderado. Você pode estudar uma combinação diversificada de alternativas de menor risco com uma parcela de investimentos sujeitos a oscilações, conforme seus objetivos, prazo e tolerância a perdas. Entenda os riscos e custos antes de investir.",
  Arrojado: "Seu perfil é arrojado. Você pode estudar investimentos com maior potencial de retorno e maior volatilidade, como ações e fundos de índice, sempre considerando diversificação, horizonte de longo prazo e a possibilidade de perdas relevantes."
};

return clientes.map((cliente, indice) => {
  const nome = String(cliente.nome ?? '').trim();
  const email = String(cliente.email ?? '').trim();
  const perfilOriginal = String(cliente.perfil ?? '').trim();
  const chavePerfil = perfilOriginal.toLowerCase();
  const perfis = {
    conservador: 'Conservador',
    moderado: 'Moderado',
    arrojado: 'Arrojado'
  };
  const perfil = perfis[chavePerfil] ?? perfilOriginal;
  const saldoTexto = String(cliente.saldo ?? '').trim();
  const saldo = Number(saldoTexto.replace(/\s/g, '').replace(/R\$/i, '').replace(/\.(?=\d{3}(?:\D|$))/g, '').replace(',', '.'));

  return {
    json: {
      nome: nome || `Cliente ${indice + 1}`,
      email,
      saldo: Number.isFinite(saldo) ? saldo : cliente.saldo ?? null,
      perfil: perfil || 'Não informado',
      mensagem: mensagens[perfil] ?? "Não foi possível identificar o perfil de investimento. Revise o cadastro do cliente antes de gerar uma mensagem.",
      observacao: "Conteúdo educativo, não é recomendação financeira personalizada."
    }
  };
});
